excels.excel:

EXPORT WITH SHEET="直播带货销售明细", HEADER=true,
    MAPPING={"a":"场次","b":"主播","c":"商品名称","d":"销售数量","e":"单价","f":"销售额","g":"佣金比例","h":"佣金"},
    FORMAT={"d":"#,##0","e":"#,##0.00","f":"#,##0.00","g":"0.00%","h":"#,##0.00"},
    FORMULAS={
        F2:'D2*E2',H2:'F2*G2',
        F3:'D3*E3',H3:'F3*G3',
        F4:'D4*E4',H4:'F4*G4',
        F5:'D5*E5',H5:'F5*G5',
        F6:'D6*E6',H6:'F6*G6',
        F7:'SUM(F2:F6)',H7:'SUM(H2:H6)'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center}
    }
